<?php if(in_array($role,['admin','hr'],true)): ?><section class="panel narrow"><h2>Publish an announcement</h2><form action="<?= site_url('announcements') ?>" method="post"><?= csrf_field() ?><label>Title<input name="title" maxlength="150" required></label><label>Category<select name="category"><option value="general">General</option><option value="safety">Safety reminder</option></select></label><label>Message<textarea name="body" minlength="5" maxlength="5000" rows="5" required></textarea></label><button type="submit">Publish to employees</button></form></section><?php endif ?>
<section class="panel"><h2>Company notices</h2><?php if(!$announcements): ?><p>No announcements have been published.</p><?php endif ?><?php foreach($announcements as $notice): ?><article class="notice"><span class="badge"><?= esc($notice['category']) ?></span><h3><?= esc($notice['title']) ?></h3><p class="pre-line"><?= esc($notice['body']) ?></p><small><?= esc($notice['created_at']) ?></small></article><?php endforeach ?></section>
